using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Authentication.Cookies;
using Microsoft.AspNetCore.Authentication.OpenIdConnect;
using Microsoft.AspNetCore.Antiforgery;
using Microsoft.AspNetCore.DataProtection;
using Microsoft.AspNetCore.Http.Features;
using Microsoft.AspNetCore.RateLimiting;
using Microsoft.IdentityModel.Tokens;
using System.Threading.RateLimiting;
using System.Security.Claims;
using System.Security.Cryptography;
using System.Net;
using System.Net.Mail;
using System.Text.Encodings.Web;
using System.Text;
using Microsoft.Data.Sqlite;

var b=WebApplication.CreateBuilder(args);
string Required(string key) => !string.IsNullOrWhiteSpace(b.Configuration[key]) ? b.Configuration[key]! : throw new InvalidOperationException($"Missing configuration: {key}");
var tenant=Guid.Parse(Required("Entra:TenantId")).ToString();
var client=Guid.Parse(Required("Entra:ClientId")).ToString();
var origin=new Uri(Required("Portal:PublicOrigin"));
if(origin.Scheme!="https" || origin.AbsolutePath!="/" || origin.Query!="" || origin.Fragment!="") throw new InvalidOperationException("PublicOrigin must be an HTTPS origin.");
var root=Path.GetFullPath(Required("Portal:DataDirectory"));
if(root.StartsWith(Path.GetFullPath(b.Environment.ContentRootPath)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase) || root==Path.GetFullPath(b.Environment.ContentRootPath)) throw new InvalidOperationException("DataDirectory must be outside the application directory.");
Directory.CreateDirectory(root); Directory.CreateDirectory(Path.Combine(root,"keys"));
var dp=b.Services.AddDataProtection().SetApplicationName("SIRK.Access").PersistKeysToFileSystem(new DirectoryInfo(Path.Combine(root,"keys")));
if(OperatingSystem.IsWindows()) dp.ProtectKeysWithDpapi();
else if(!b.Environment.IsDevelopment()) throw new InvalidOperationException("Production requires Windows DPAPI in this release.");
b.Services.AddSingleton(sp=>new Store(root,sp.GetRequiredService<IDataProtectionProvider>()));
b.Services.AddHostedService<Cleanup>();
b.Services.Configure<FormOptions>(o=>{o.MultipartBodyLengthLimit=105L*1024*1024;o.ValueLengthLimit=65536;});
b.WebHost.ConfigureKestrel(o=>o.Limits.MaxRequestBodySize=110L*1024*1024);
b.Services.AddAuthentication(o=>{o.DefaultScheme="cookie";o.DefaultChallengeScheme="oidc";})
.AddCookie("cookie",o=>{o.Cookie.Name="__Host-SirkAccess";o.Cookie.SecurePolicy=CookieSecurePolicy.Always;o.Cookie.HttpOnly=true;o.Cookie.SameSite=SameSiteMode.Lax;o.Cookie.Path="/";o.ExpireTimeSpan=TimeSpan.FromMinutes(30);o.SlidingExpiration=false;})
.AddOpenIdConnect("oidc",o=>{
    o.Authority=$"https://login.microsoftonline.com/{tenant}/v2.0";o.ClientId=client;o.ClientSecret=Required("Entra:ClientSecret");o.ResponseType="code";o.UsePkce=true;o.MapInboundClaims=false;o.SaveTokens=false;
    o.TokenValidationParameters=new TokenValidationParameters{ NameClaimType="name",RoleClaimType="roles",ValidateIssuer=true,ValidateAudience=true };
    o.Events.OnTokenValidated=ctx=>{
        var principal=ctx.Principal;
        if(principal is null || !Guid.TryParse(principal.FindFirst("tid")?.Value,out var tid) || tid!=Guid.Parse(tenant) || !Guid.TryParse(principal.FindFirst("oid")?.Value,out var oid))
            ctx.Fail("Invalid tenant or object id.");
        else {
            var h=ctx.HttpContext;
            h.RequestServices.GetRequiredService<Store>().Audit(oid.ToString("D"),h.Connection.RemoteIpAddress?.ToString()??"", "auth.login","entra","success",h.TraceIdentifier);
        }
        return Task.CompletedTask;
    };
    o.Events.OnRemoteFailure=ctx=>{var h=ctx.HttpContext;h.RequestServices.GetRequiredService<Store>().Audit("anonymous",h.Connection.RemoteIpAddress?.ToString()??"","auth.login","entra","failure",h.TraceIdentifier);ctx.HandleResponse();h.Response.StatusCode=401;return h.Response.WriteAsync("Authentication failed.");};
});
b.Services.AddAuthorization(o=>{o.AddPolicy("Portal",p=>p.RequireAuthenticatedUser().RequireRole("Admin","Employee","Helpdesk","External","Auditor"));o.AddPolicy("Writer",p=>p.RequireRole("Admin","Employee","Helpdesk"));o.AddPolicy("Admin",p=>p.RequireRole("Admin"));o.AddPolicy("Audit",p=>p.RequireRole("Admin","Auditor"));});
b.Services.AddAntiforgery(o=>{o.HeaderName="X-CSRF";o.Cookie.Name="__Host-SirkCsrf";o.Cookie.SecurePolicy=CookieSecurePolicy.Always;o.Cookie.Path="/";});
b.Services.AddRateLimiter(o=>{o.RejectionStatusCode=429;o.AddPolicy("click",h=>RateLimitPartition.GetFixedWindowLimiter(h.Connection.RemoteIpAddress?.ToString()??"unknown",_=>new FixedWindowRateLimiterOptions{PermitLimit=240,Window=TimeSpan.FromMinutes(1),QueueLimit=0}));o.AddPolicy("public",h=>RateLimitPartition.GetFixedWindowLimiter(h.Connection.RemoteIpAddress?.ToString()??"unknown",_=>new FixedWindowRateLimiterOptions{PermitLimit=20,Window=TimeSpan.FromMinutes(1),QueueLimit=0}));});
var app=b.Build(); var db=app.Services.GetRequiredService<Store>(); db.Init();
app.Use(async (h,next)=>{
    h.Response.Headers["Cache-Control"]="no-store";h.Response.Headers["Referrer-Policy"]="no-referrer";h.Response.Headers["X-Content-Type-Options"]="nosniff";h.Response.Headers["X-Frame-Options"]="DENY";h.Response.Headers["Content-Security-Policy"]="default-src 'none'; script-src 'self'; style-src 'self'; img-src 'self'; connect-src 'self'; form-action 'self' https://login.microsoftonline.com; frame-ancestors 'none'; base-uri 'none'";h.Response.Headers["Permissions-Policy"]="camera=(), microphone=(), geolocation=()";
    if(!h.Request.IsHttps || !string.Equals(h.Request.Host.Value,origin.Authority,StringComparison.OrdinalIgnoreCase)){h.Response.StatusCode=400;return;}
    h.Response.Headers["Strict-Transport-Security"]="max-age=31536000";await next();
});
app.UseRouting();
// Audit callback requests without logging query strings, bodies or untrusted URL segments.
app.Use(async(h,next)=>{
    var route=(h.GetEndpoint() as RouteEndpoint)?.RoutePattern.RawText ?? (h.Request.Path=="/signin-oidc"?"oidc.callback":"unmapped");
    var failed=false; try { await next(); } catch { failed=true; throw; } finally { db.Audit(Actor(h),Ip(h),"http."+h.Request.Method,route,failed?"500":h.Response.StatusCode.ToString(),h.TraceIdentifier); }
});
app.UseAuthentication();app.UseRateLimiter();app.UseAuthorization();
app.Use(async(h,next)=>{if(h.Request.Method=="POST") {try{await h.RequestServices.GetRequiredService<IAntiforgery>().ValidateRequestAsync(h);}catch(AntiforgeryValidationException){h.Response.StatusCode=400;return;}}await next();});
app.UseStaticFiles();
string E(string? s)=>HtmlEncoder.Default.Encode(s??"");
string Actor(HttpContext h)=>h.User.FindFirstValue("oid")??"anonymous";
string Ip(HttpContext h)=>h.Connection.RemoteIpAddress?.ToString()??"";
void Audit(HttpContext h,string action,string target,string outcome="success")=>db.Audit(Actor(h),Ip(h),action,target,outcome,h.TraceIdentifier);
string Csrf(HttpContext h)=>"<input type='hidden' name='__RequestVerificationToken' value='"+E(h.RequestServices.GetRequiredService<IAntiforgery>().GetAndStoreTokens(h).RequestToken)+"'>";
string Form(HttpContext h,string path,string body,string label)=>$"<form method='post' action='{path}'>{Csrf(h)}{body}<button>{E(label)}</button></form>";
string Input(string name,string label,string type="text",string extra="")=>$"<label>{E(label)}<input name='{name}' type='{type}' {extra}></label>";
IResult Page(HttpContext h,string title,string body,int status=200){var auth=h.User.Identity?.IsAuthenticated==true;var nav=auth?"<a href='/'>Dashboard</a><a href='/notes'>Notes</a>"+(h.User.IsInRole("Admin")?"<a href='/admin'>Administration</a>":"")+(h.User.IsInRole("Admin")||h.User.IsInRole("Auditor")?"<a href='/audit'>Audit</a>":"")+Form(h,"/logout","","Sign out"):"<a href='/login'>Sign in with Entra</a>";return Results.Content($"<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='csrf' content='{E(h.RequestServices.GetRequiredService<IAntiforgery>().GetAndStoreTokens(h).RequestToken)}'><title>{E(title)} | SIRK Access Portal</title><link rel='stylesheet' href='/portal.css'><script src='/portal.js' defer></script></head><body><header><strong>SIRK Access Portal</strong><nav>{nav}</nav></header><main><h1>{E(title)}</h1>{body}</main><footer>Secure access &amp; information sharing</footer></body></html>","text/html; charset=utf-8",statusCode:status);}
IResult Denied(HttpContext h)=>Page(h,"Access denied","<p>Resource unavailable or authorization failed.</p>",403);
string F(IFormCollection f,string k)=>f[k].ToString().Trim();
bool TokenValid(string t)=>t.Length==64&&t.All(Uri.IsHexDigit);
bool EmailValid(string e)=>e.Length<=254&&MailAddress.TryCreate(e,out var a)&&string.Equals(a.Address,e,StringComparison.OrdinalIgnoreCase);
bool CanAccess(HttpContext h,string audience)=>audience=="Employee"&&h.User.IsInRole("Employee")||audience=="External"&&h.User.IsInRole("External")||audience=="Helpdesk"&&h.User.IsInRole("Helpdesk")||audience=="Admin"&&h.User.IsInRole("Admin")||audience=="oid:"+Actor(h);
bool AudienceValid(string a)=>new[]{"Employee","External","Helpdesk","Admin"}.Contains(a)||(a.StartsWith("oid:",StringComparison.Ordinal)&&Guid.TryParseExact(a[4..],"D",out _)&&a==a.ToLowerInvariant());
app.MapGet("/login",()=>Results.Challenge(new AuthenticationProperties{RedirectUri="/"},["oidc"]));
app.MapGet("/login-note",()=>Results.Challenge(new AuthenticationProperties{RedirectUri="/receive"},["oidc"]));
app.MapPost("/logout",(HttpContext h)=>{Audit(h,"auth.logout","session");return Results.SignOut(new AuthenticationProperties{RedirectUri="/receive"},["cookie","oidc"]);}).RequireAuthorization("Portal");
app.MapGet("/",(HttpContext h)=>{
    using var c=db.Open();using var q=Store.Cmd(c,"SELECT id,title,category,kind,audience FROM resources WHERE enabled=1 ORDER BY category,title");using var r=q.ExecuteReader();var html=new StringBuilder("<p>Signed in as "+E(h.User.Identity?.Name)+"</p><div class='tiles'>");while(r.Read()){if(CanAccess(h,r.GetString(4)))html.Append($"<a class='tile' href='/resource/{E(r.GetString(0))}'><small>{E(r.GetString(2))} / {E(r.GetString(3))}</small><h2>{E(r.GetString(1))}</h2></a>");}html.Append("</div><p><a href='/receive'>Open a secure note</a></p>");if(h.User.IsInRole("Admin")||h.User.IsInRole("Employee")||h.User.IsInRole("Helpdesk"))html.Append("<p><a href='/notes/new'>Create secure note</a></p>");return Page(h,"My resources",html.ToString());
}).RequireAuthorization("Portal");
app.MapGet("/notes",(HttpContext h)=>{using var c=db.Open();using var q=Store.Cmd(c,"SELECT id,mode,recipient,expires,remaining,state FROM notes WHERE owner=$o ORDER BY expires DESC LIMIT 200",("$o",Actor(h)));using var r=q.ExecuteReader();var s=new StringBuilder("<p><a href='/receive'>Receive a note</a> | <a href='/notes/new'>Create note</a></p><table><tr><th>Mode</th><th>Recipient</th><th>Expires UTC</th><th>Reads left</th><th>Status</th><th>Action</th></tr>");while(r.Read())s.Append($"<tr><td>{E(r.GetString(1))}</td><td>{E(r.GetString(2))}</td><td>{DateTimeOffset.FromUnixTimeSeconds(r.GetInt64(3)):u}</td><td>{r.GetInt32(4)}</td><td>{E(r.GetString(5))}</td><td>{Form(h,"/notes/revoke","<input type='hidden' name='id' value='"+E(r.GetString(0))+"'>","Revoke")}</td></tr>");return Page(h,"Sent notes",s.Append("</table>").ToString());}).RequireAuthorization("Portal");
app.MapGet("/notes/new",(HttpContext h)=>Page(h,"Create secure note",Form(h,"/notes/new","<label>Mode<select name='mode'><option value='external'>External email OTP</option><option value='sso'>Entra SSO (object ID)</option></select></label>"+Input("recipient","Recipient email or Entra object ID","text","required maxlength='254'")+Input("hours","Lifetime (hours)","number",$"min='1' max='{db.Setting("max_hours")}' value='24' required")+Input("reads","Maximum reads","number",$"min='1' max='{db.Setting("max_reads")}' value='1' required")+"<label>Secret<textarea name='message' maxlength='16384' required autocomplete='off'></textarea></label>","Create note"))).RequireAuthorization("Writer");
app.MapPost("/notes/new",async (HttpContext h)=>{var f=await h.Request.ReadFormAsync();var mode=F(f,"mode");var recipient=F(f,"recipient").ToLowerInvariant();var message=f["message"].ToString();if(!(mode=="external"&&db.Setting("external_enabled")==1&&EmailValid(recipient)||mode=="sso"&&Guid.TryParseExact(recipient,"D",out _))||!int.TryParse(F(f,"hours"),out var hours)||hours<1||hours>db.Setting("max_hours")||!int.TryParse(F(f,"reads"),out var reads)||reads<1||reads>db.Setting("max_reads")||message.Length is <1 or >16384)return Page(h,"Invalid note","<p>Check policy and recipient.</p>",400);var id=Store.Id();var token=Store.Id();var enc=db.Encrypt(id,message);using var c=db.Open();using var q=Store.Cmd(c,"INSERT INTO notes(id,token,owner,mode,recipient,expires,remaining,payload,wrapped) VALUES($id,$t,$o,$m,$r,$e,$n,$p,$w)",("$id",id),("$t",Store.Hash(token)),("$o",Actor(h)),("$m",mode),("$r",recipient),("$e",Store.Now+hours*3600L),("$n",reads),("$p",enc.payload),("$w",enc.wrapped));q.ExecuteNonQuery();Audit(h,"note.create",id);return Page(h,"Note created","<p>Copy this link. It is shown only once.</p><textarea readonly id='share-link'>"+E(origin.GetLeftPart(UriPartial.Authority)+"/receive#"+token)+"</textarea><button type='button' data-copy='share-link'>Copy link</button><p>Use a separate trusted channel for the link when possible.</p>");}).RequireAuthorization("Writer");
app.MapPost("/notes/revoke",async (HttpContext h)=>{var f=await h.Request.ReadFormAsync();var id=F(f,"id");using var c=db.Open();using var q=Store.Cmd(c,"UPDATE notes SET state='revoked',payload=NULL,wrapped=NULL,otp=NULL WHERE id=$i AND owner=$o AND state='active'",("$i",id),("$o",Actor(h)));Audit(h,"note.revoke",TokenValid(id)?id:"invalid",q.ExecuteNonQuery()==1?"success":"denied");return Results.Redirect("/notes");}).RequireAuthorization("Portal");
app.MapGet("/receive",(HttpContext h)=>Page(h,"Receive secure note","<p>Use the original link or paste its access code. For internal notes, <a href='/login-note'>sign in with Entra</a> first.</p>"+Form(h,"/notes/otp",Input("token","Access code","text","required maxlength='64' data-note-token")+Input("email","Recipient email","email","required maxlength='254'"),"Send verification code")+Form(h,"/notes/read",Input("token","Access code","text","required maxlength='64' data-note-token")+Input("email","Recipient email (external notes only)","email","maxlength='254'")+Input("otp","Verification code (external notes only)","text","maxlength='8' autocomplete='one-time-code'"),"Reveal note")));
app.MapPost("/notes/otp",async (HttpContext h)=>{
    var f=await h.Request.ReadFormAsync();var token=F(f,"token");var email=F(f,"email").ToLowerInvariant();var code=RandomNumberGenerator.GetInt32(0,100000000).ToString("D8");var now=Store.Now;var sent=false;
    if(TokenValid(token)&&EmailValid(email)&&db.Setting("external_enabled")==1){using var c=db.Open();using var q=Store.Cmd(c,"UPDATE notes SET otp=$otp,otp_exp=$exp,otp_sent=$now,attempts=0 WHERE token=$t AND recipient=$r AND mode='external' AND state='active' AND expires>$now AND remaining>0 AND otp_sent<=$cool",("$otp",db.ProtectOtp(code)),("$exp",now+300),("$now",now),("$t",Store.Hash(token)),("$r",email),("$cool",now-60));if(q.ExecuteNonQuery()==1){try{using var smtp=new SmtpClient(Required("Portal:SmtpHost"),b.Configuration.GetValue("Portal:SmtpPort",587)){EnableSsl=true,Timeout=15000,Credentials=new NetworkCredential(Required("Portal:SmtpUser"),Required("Portal:SmtpPassword"))};using var mail=new MailMessage(Required("Portal:SmtpFrom"),email,"SIRK Access verification code","Your verification code: "+code+". Expires in 5 minutes.");await smtp.SendMailAsync(mail);sent=true;}catch(Exception ex){app.Logger.LogWarning("OTP delivery failed: {Type}",ex.GetType().Name);}}}Audit(h,"note.otp","external",sent?"sent":"not_sent");return Page(h,"Verification","<p>If the request is valid, a verification code has been sent.</p><a href='/receive'>Return to note</a>");
}).RequireRateLimiting("public");
app.MapPost("/notes/read",async (HttpContext h)=>{
    var f=await h.Request.ReadFormAsync();var token=F(f,"token");if(!TokenValid(token)){Audit(h,"note.read","invalid","denied");return Denied(h);}var hash=Store.Hash(token);using var c=db.Open();using var tx=c.BeginTransaction(deferred:false);using var q=Store.Cmd(c,"SELECT id,mode,recipient,remaining,payload,wrapped,otp,otp_exp,attempts FROM notes WHERE token=$t AND state='active' AND expires>$now AND remaining>0",("$t",hash),("$now",Store.Now));q.Transaction=tx;using var r=q.ExecuteReader();if(!r.Read()){r.Close();tx.Commit();Audit(h,"note.read","unknown","denied");return Denied(h);}var id=r.GetString(0);var mode=r.GetString(1);var recipient=r.GetString(2);var left=r.GetInt32(3);var payload=(byte[])r[4];var wrapped=(byte[])r[5];var otp=r.IsDBNull(6)?null:r.GetString(6);var exp=r.GetInt64(7);var attempts=r.GetInt32(8);r.Close();var ok=mode=="sso"&&h.User.Identity?.IsAuthenticated==true&&Actor(h)==recipient&&(new[]{"Admin","Employee","External","Helpdesk","Auditor"}.Any(h.User.IsInRole));
    if(mode=="external"&&db.Setting("external_enabled")==1&&recipient==F(f,"email").ToLowerInvariant()&&otp!=null&&exp>Store.Now&&attempts<5){ok=db.VerifyOtp(otp,F(f,"otp"));if(!ok){using var fail=Store.Cmd(c,"UPDATE notes SET attempts=attempts+1 WHERE id=$i",("$i",id));fail.Transaction=tx;fail.ExecuteNonQuery();}}
    if(!ok){tx.Commit();Audit(h,"note.read",id,"denied");return Denied(h);}var plain=db.Decrypt(id,payload,wrapped);using var update=Store.Cmd(c,"UPDATE notes SET remaining=remaining-1,state=CASE WHEN remaining=1 THEN 'consumed' ELSE state END,payload=CASE WHEN remaining=1 THEN NULL ELSE payload END,wrapped=CASE WHEN remaining=1 THEN NULL ELSE wrapped END,otp=NULL,otp_exp=0 WHERE id=$i",("$i",id));update.Transaction=tx;update.ExecuteNonQuery();using var aq=Store.Cmd(c,"INSERT INTO audit(at,actor,ip,action,target,outcome,trace) VALUES($at,$a,$ip,'note.read',$i,'success',$tr)",("$at",Store.Now),("$a",Actor(h)),("$ip",Ip(h)),("$i",id),("$tr",h.TraceIdentifier));aq.Transaction=tx;aq.ExecuteNonQuery();tx.Commit();return Page(h,"Secure note","<p>Access count consumed. Copy the information before leaving.</p><textarea readonly id='secret'>"+E(plain)+"</textarea><button type='button' data-copy='secret'>Copy secret</button>");
}).RequireRateLimiting("public");
