app.MapPost("/admin/settings",async (HttpContext h)=>{var f=await h.Request.ReadFormAsync();if(!int.TryParse(F(f,"max_hours"),out var hours)||hours is <1 or >720||!int.TryParse(F(f,"max_reads"),out var reads)||reads is <1 or >100||!int.TryParse(F(f,"external_enabled"),out var enabled)||enabled is <0 or >1)return Page(h,"Invalid policy","<p>Check policy limits.</p>",400);using var c=db.Open();using var tx=c.BeginTransaction();foreach(var (key,value) in new[]{("max_hours",hours),("max_reads",reads),("external_enabled",enabled)}){using var q=Store.Cmd(c,"UPDATE settings SET value=$v WHERE name=$k",("$v",value),("$k",key));q.Transaction=tx;q.ExecuteNonQuery();}tx.Commit();Audit(h,"admin.settings","note-policy");return Results.Redirect("/admin");}).RequireAuthorization("Admin");
