bool ValidLink(string target)=>target.Length<=2048&&Uri.TryCreate(target,UriKind.Absolute,out var u)&&u.Scheme=="https"&&u.UserInfo==""&&u.Host.Length>0;
app.MapPost("/admin/link",async (HttpContext h)=>{var f=await h.Request.ReadFormAsync();var title=F(f,"title");var cat=F(f,"category");var aud=F(f,"audience");var target=F(f,"target");if(!ValidMetadata(title,cat,aud)||!ValidLink(target))return Page(h,"Invalid resource","<p>Check the fields.</p>",400);var id=Store.Id();using var c=db.Open();using var q=Store.Cmd(c,"INSERT INTO resources(id,title,category,kind,target,audience) VALUES($i,$t,$c,'link',$u,$a)",("$i",id),("$t",title),("$c",cat),("$u",target),("$a",aud));q.ExecuteNonQuery();Audit(h,"admin.resource.create",id);return Results.Redirect("/admin");}).RequireAuthorization("Admin");
app.MapPost("/admin/upload",async (HttpContext h)=>{var f=await h.Request.ReadFormAsync();var title=F(f,"title");var cat=F(f,"category");var aud=F(f,"audience");var file=f.Files.GetFile("file");if(!ValidMetadata(title,cat,aud)||file==null||file.Length is <=0 or >104857600)return Page(h,"Invalid upload","<p>Maximum 100 MiB.</p>",400);var name=Path.GetFileName(file.FileName.Replace('\\','/'));if(name.Length is <1 or >200||name.Any(char.IsControl)||!new[]{".pdf",".msi",".exe",".zip",".docx",".xlsx",".txt",".msix"}.Contains(Path.GetExtension(name).ToLowerInvariant()))return Page(h,"Invalid upload","<p>File extension not allowed.</p>",400);var id=Store.Id();var path=Path.Combine(db.Files,id);try{await using(var dest=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.None)){await file.CopyToAsync(dest,h.RequestAborted);}string hash;await using(var src=File.OpenRead(path)){hash=Convert.ToHexString(await SHA256.HashDataAsync(src,h.RequestAborted));}using var c=db.Open();using var q=Store.Cmd(c,"INSERT INTO resources(id,title,category,kind,target,audience,filename,sha) VALUES($i,$t,$c,'file','',$a,$f,$s)",("$i",id),("$t",title),("$c",cat),("$a",aud),("$f",name),("$s",hash));q.ExecuteNonQuery();}catch{File.Delete(path);throw;}Audit(h,"admin.file.upload",id);return Results.Redirect("/admin");}).RequireAuthorization("Admin");
app.MapGet("/admin/edit/{id}",(HttpContext h,string id)=>{if(!TokenValid(id))return Denied(h);using var c=db.Open();using var q=Store.Cmd(c,"SELECT title,category,audience,kind,target FROM resources WHERE id=$i",("$i",id));using var r=q.ExecuteReader();if(!r.Read())return Denied(h);string Value(string v)=>"required value='"+E(v)+"'";return Page(h,"Edit resource",Form(h,"/admin/edit","<input type='hidden' name='id' value='"+E(id)+"'>"+Input("title","Title","text",Value(r.GetString(0)))+Input("category","Category","text",Value(r.GetString(1)))+Input("audience","Audience","text",Value(r.GetString(2)))+(r.GetString(3)=="link"?Input("target","HTTPS URL","url",Value(r.GetString(4))):""),"Save and disable pending review"));}).RequireAuthorization("Admin");
app.MapPost("/admin/edit",async (HttpContext h)=>{var f=await h.Request.ReadFormAsync();var id=F(f,"id");var title=F(f,"title");var cat=F(f,"category");var aud=F(f,"audience");var target=F(f,"target");if(!TokenValid(id)||!ValidMetadata(title,cat,aud)||(target!=""&&!ValidLink(target)))return Denied(h);using var c=db.Open();using var q=Store.Cmd(c,"UPDATE resources SET title=$t,category=$c,audience=$a,target=CASE WHEN kind='link' THEN $u ELSE target END,enabled=0 WHERE id=$i AND (kind='file' OR $u<>'')",("$i",id),("$t",title),("$c",cat),("$a",aud),("$u",target));Audit(h,"admin.resource.edit",id,q.ExecuteNonQuery()==1?"success":"denied");return Results.Redirect("/admin");}).RequireAuthorization("Admin");
app.MapPost("/admin/toggle",async (HttpContext h)=>{var f=await h.Request.ReadFormAsync();var id=F(f,"id");if(!TokenValid(id)||!int.TryParse(F(f,"enabled"),out var enabled)||enabled is <0 or >1)return Denied(h);using var c=db.Open();using var q=Store.Cmd(c,"UPDATE resources SET enabled=$e WHERE id=$i",("$i",id),("$e",enabled));Audit(h,enabled==1?"admin.resource.publish":"admin.resource.disable",id,q.ExecuteNonQuery()==1?"success":"denied");return Results.Redirect("/admin");}).RequireAuthorization("Admin");
app.MapPost("/admin/revoke",async (HttpContext h)=>{var f=await h.Request.ReadFormAsync();var id=F(f,"id");if(!TokenValid(id))return Denied(h);using var c=db.Open();using var q=Store.Cmd(c,"UPDATE notes SET state='revoked',payload=NULL,wrapped=NULL,otp=NULL WHERE id=$i AND state='active'",("$i",id));Audit(h,"admin.note.revoke",id,q.ExecuteNonQuery()==1?"success":"denied");return Results.Redirect("/admin");}).RequireAuthorization("Admin");
app.MapGet("/audit",(HttpContext h)=>{Audit(h,"audit.view","events");using var c=db.Open();using var q=Store.Cmd(c,"SELECT at,actor,ip,action,target,outcome,trace FROM audit ORDER BY id DESC LIMIT 500");using var r=q.ExecuteReader();var s=new StringBuilder("<p>Latest 500 events. No secret contents, OTP or bearer tokens are collected.</p><table><tr><th>UTC</th><th>Actor</th><th>IP</th><th>Action</th><th>Target</th><th>Outcome</th><th>Trace</th></tr>");while(r.Read()){s.Append("<tr><td>"+DateTimeOffset.FromUnixTimeSeconds(r.GetInt64(0)).ToString("u")+"</td>");for(int i=1;i<7;i++)s.Append("<td>"+E(r.GetString(i))+"</td>");s.Append("</tr>");}return Page(h,"Audit log",s.Append("</table>").ToString());}).RequireAuthorization("Audit");
app.MapPost("/audit/click",async (HttpContext h)=>{var f=await h.Request.ReadFormAsync();var type=F(f,"type");var target=F(f,"target");var allowed=new[]{"nav","submit","copy","resource","field","other"};if(!allowed.Contains(type))return Results.BadRequest();var known=new[]{"dashboard","notes","receive","admin","audit","login","logout","create","otp","read","revoke","settings","link","upload","toggle","edit","share-link","secret","other"};if(!known.Contains(target)){if(type=="resource"&&TokenValid(target)){using var c=db.Open();using var q=Store.Cmd(c,"SELECT count(*) FROM resources WHERE id=$i",("$i",target));if(Convert.ToInt32(q.ExecuteScalar())!=1)target="other";}else target="other";}Audit(h,"ui.click."+type,target);return Results.NoContent();}).RequireRateLimiting("click");
app.Run();
